mapper.select:
SELECT t.TRADEIDX as "tradeIdx", t.PRODUCTIDX as "productIdx", b.USERID as "buyerId", b.NICKNAME as "buyerNickname", s.USERID as "sellerId", s.NICKNAME as "sellerNickname", t.TRADEPRICE as "tradePrice", t.SAFETYFEE as "safetyFee", t.TOTALUSED_POINT as "totalUsedPoint", TO_CHAR(t.TRADEDATE, 'YYYY-MM-DD HH24:MI') as "tradeDate", t.TRADESTATUS as "tradeStatus" FROM TRADETRANSACTION t JOIN users b ON t.BUYERIDX = b.USERIDX JOIN users s ON t.SELLERIDX = s.USERIDX
AND t.TRADESTATUS = #{status}
ORDER BY t.TRADEDATE DESC OFFSET #{offset} ROWS FETCH NEXT #{pageSize} ROWS ONLY
